import React, { useState, useEffect } from "react";
import axios from "axios";

const Summary = () => {
  const apiUrl = `http://${window.location.hostname}:3002`;

  const [allHoldings, setAllHoldings] = useState([]);

  useEffect(() => {
    const fetchHoldings = async () => {
      try {
        const res = await axios.get(`${apiUrl}/api/allHoldings`, {
          withCredentials: true
        });

        setAllHoldings(res.data);
      } catch (err) {
        console.log("Failed to fetch holdings:", err);
      }
    };

    fetchHoldings();
  }, []);

  // Total investment
  const investment = allHoldings.reduce(
    (total, stock) => total + stock.avg * stock.qty,
    0
  );

  // Current value
  const currentValue = allHoldings.reduce(
    (total, stock) => total + stock.price * stock.qty,
    0
  );

  // Profit / Loss
  const pnl = currentValue - investment;

  // Profit / Loss percentage
  const pnlPercentage =
    investment > 0 ? (pnl / investment) * 100 : 0;

  const isProfit = pnl >= 0;

  return (
    <>
      <div className="username">
        <h6>Hi, User!</h6>
        <hr className="divider" />
      </div>

      <div className="section">
        <span>
          <p>Equity</p>
        </span>

        <div className="data">
          <div className="first">
            <h3>3.74k</h3>
            <p>Margin available</p>
          </div>

          <hr />

          <div className="second">
            <p>
              Margins used <span>0</span>
            </p>

            <p>
              Opening balance <span>3.74k</span>
            </p>
          </div>
        </div>

        <hr className="divider" />
      </div>

      <div className="section">
        <span>
          <p>Holdings ({allHoldings.length})</p>
        </span>

        <div className="data">
          <div className="first">
            <h3 className={isProfit ? "profit" : "loss"}>
              {Math.abs(pnl).toFixed(2)}
              <small>
                {" "}
                {isProfit ? "+" : "-"}
                {Math.abs(pnlPercentage).toFixed(2)}%
              </small>
            </h3>

            <p>P&L</p>
          </div>

          <hr />

          <div className="second">
            <p>
              Current Value{" "}
              <span>{currentValue.toFixed(2)}</span>
            </p>

            <p>
              Investment{" "}
              <span>{investment.toFixed(2)}</span>
            </p>
          </div>
        </div>

        <hr className="divider" />
      </div>
    </>
  );
};

export default Summary;
